    if(seoFiltrKategorii!=="wszystkie"&&String(p.kategoria||"")!==seoFiltrKategorii)return false;if(seoFiltrProducenta!=="wszyscy"&&String(p.producent||p.marka||"")!==seoFiltrProducenta)return false;
    return true;
